-- 25 workout programs
insert into public.workout_programs (id, title, description, training_type, subcategory, level, weeks, days_per_week, duration_minutes, equipment, category, is_premium, image_color, coach_tip, exercises, modules, weekly_schedule, status) values
  ('f1', 'Fat Loss Accelerator', '8-week fat loss program combining HIIT, circuit training, and steady-state cardio to maximize caloric burn while preserving lean muscle.', 'fitness', 'Weight Loss', 'Beginner', 8, 4, 40, array['Dumbbells', 'Jump Rope', 'Mat']::text[], 'Fitness', false, '#FF6B35', 'Pair this program with a 200–400 calorie daily deficit for optimal fat loss. Track weekly weight and adjust portions — not exercise intensity — when progress stalls.', '[{"id":"f1e1","name":"Jump Rope Warmup","sets":1,"reps":"3 min","rest":"30s","muscleGroup":"Full Body / Cardio","notes":"Moderate pace — elevate heart rate without burning out"},{"id":"f1e2","name":"Dumbbell Squat","sets":3,"reps":"15","rest":"45s","muscleGroup":"Quads / Glutes","weight":"15–25 lbs"},{"id":"f1e3","name":"Push-Up to Mountain Climber","sets":3,"reps":"10 + 20","rest":"45s","muscleGroup":"Chest / Core","notes":"10 push-ups then 20 mountain climbers — no rest between"},{"id":"f1e4","name":"Dumbbell Romanian Deadlift","sets":3,"reps":"12","rest":"60s","muscleGroup":"Hamstrings / Glutes","weight":"20–35 lbs"},{"id":"f1e5","name":"Burpee","sets":4,"reps":"10","rest":"30s","muscleGroup":"Full Body","notes":"Rest 90s every other set if needed as a beginner"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"HIIT Circuit","duration":40,"type":"conditioning"},{"day":"Tuesday","label":"Active Recovery","duration":30,"type":"recovery"},{"day":"Wednesday","label":"Strength + Cardio","duration":45,"type":"strength"},{"day":"Thursday","label":"Rest","duration":0,"type":"rest"},{"day":"Friday","label":"HIIT Circuit","duration":40,"type":"conditioning"},{"day":"Saturday","label":"Cardio Burn","duration":35,"type":"conditioning"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('f2', 'Muscle Building Hypertrophy', '12-week hypertrophy program built on proven push/pull/legs splits. Progressive overload drives muscle growth week over week.', 'fitness', 'Muscle Building', 'Intermediate', 12, 5, 60, array['Barbell', 'Dumbbells', 'Pull-Up Bar', 'Bench', 'Cable Machine']::text[], 'Fitness', true, '#9C27B0', 'Eat at least 0.8g of protein per pound of bodyweight each day. Sleep is when muscle is built — aim for 7–9 hours consistently.', '[{"id":"f2e1","name":"Barbell Bench Press","sets":4,"reps":"8–10","rest":"90s","muscleGroup":"Chest","weight":"65–75% 1RM"},{"id":"f2e2","name":"Incline Dumbbell Press","sets":3,"reps":"10–12","rest":"75s","muscleGroup":"Upper Chest","weight":"30–45 lbs"},{"id":"f2e3","name":"Pull-Up","sets":4,"reps":"6–10","rest":"90s","muscleGroup":"Back / Biceps","notes":"Use band assistance if needed"},{"id":"f2e4","name":"Barbell Squat","sets":4,"reps":"8","rest":"2 min","muscleGroup":"Quads / Glutes","weight":"70–80% 1RM"},{"id":"f2e5","name":"Seated Dumbbell OHP","sets":3,"reps":"10–12","rest":"75s","muscleGroup":"Shoulders","weight":"25–40 lbs"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Push (Chest/Shoulders)","duration":60,"type":"strength"},{"day":"Tuesday","label":"Pull (Back/Biceps)","duration":60,"type":"strength"},{"day":"Wednesday","label":"Legs","duration":65,"type":"strength"},{"day":"Thursday","label":"Rest","duration":0,"type":"rest"},{"day":"Friday","label":"Push","duration":60,"type":"strength"},{"day":"Saturday","label":"Pull + Legs","duration":70,"type":"strength"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('f3', 'Beginner Fitness Foundation', 'A gentle 6-week introduction to structured fitness. Full-body workouts three times per week with progressive difficulty built in.', 'fitness', 'Beginner Programs', 'Beginner', 6, 3, 30, array['Dumbbells', 'Mat']::text[], 'Fitness', false, '#35C98A', 'Consistency over intensity. Showing up three times a week every week beats sporadic hard sessions every time.', '[{"id":"f3e1","name":"Bodyweight Squat","sets":3,"reps":"12","rest":"60s","muscleGroup":"Legs"},{"id":"f3e2","name":"Push-Up (Knee or Full)","sets":3,"reps":"8–12","rest":"60s","muscleGroup":"Chest / Triceps","notes":"Start on knees and progress to full push-up by week 4"},{"id":"f3e3","name":"Dumbbell Row","sets":3,"reps":"10 each","rest":"60s","muscleGroup":"Back / Biceps","weight":"10–20 lbs"},{"id":"f3e4","name":"Glute Bridge","sets":3,"reps":"15","rest":"45s","muscleGroup":"Glutes / Hamstrings"},{"id":"f3e5","name":"Plank Hold","sets":3,"reps":"20–40s","rest":"45s","muscleGroup":"Core","notes":"Straight line from head to heel"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('f4', 'Home Workout Builder', 'Zero-equipment, full-body training you can do anywhere. Progressive bodyweight workouts that actually build real fitness.', 'fitness', 'Home Workouts', 'Beginner', 8, 4, 35, array['Mat', 'Chair']::text[], 'Fitness', false, '#2F80FF', 'Elevate your feet on a chair for decline push-ups, use a backpack full of books for weighted squats — creativity is the home gym advantage.', '[{"id":"f4e1","name":"Jump Squat","sets":3,"reps":"12","rest":"45s","muscleGroup":"Legs / Power"},{"id":"f4e2","name":"Pike Push-Up","sets":3,"reps":"10","rest":"60s","muscleGroup":"Shoulders / Triceps","notes":"Inverted V position — targets shoulder press pattern"},{"id":"f4e3","name":"Single-Leg Glute Bridge","sets":3,"reps":"12 each","rest":"45s","muscleGroup":"Glutes / Hamstrings"},{"id":"f4e4","name":"Tricep Dip (Chair)","sets":3,"reps":"12","rest":"45s","muscleGroup":"Triceps / Shoulders"},{"id":"f4e5","name":"Bicycle Crunch","sets":3,"reps":"20","rest":"30s","muscleGroup":"Core / Obliques"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('f5', 'Gym Strength & Conditioning', '12-week gym program building strength and conditioning simultaneously. Designed for athletes who want both muscle and cardiovascular fitness.', 'fitness', 'Gym Workouts', 'Intermediate', 12, 5, 60, array['Barbell', 'Dumbbells', 'Cables', 'Bench', 'Pull-Up Bar']::text[], 'Fitness', true, '#D6A84B', 'Superset accessory movements to keep heart rate elevated. The goal is both a muscular pump and cardiovascular challenge in every session.', '[{"id":"f5e1","name":"Barbell Back Squat","sets":4,"reps":"6–8","rest":"2 min","muscleGroup":"Legs","weight":"75–85% 1RM"},{"id":"f5e2","name":"Lat Pulldown","sets":4,"reps":"10","rest":"75s","muscleGroup":"Back / Lats"},{"id":"f5e3","name":"Dumbbell Lunge","sets":3,"reps":"10 each","rest":"60s","muscleGroup":"Quads / Glutes","weight":"20–35 lbs"},{"id":"f5e4","name":"Cable Face Pull","sets":3,"reps":"15","rest":"45s","muscleGroup":"Rear Delts / Rotator Cuff"},{"id":"f5e5","name":"Treadmill Interval Sprint","sets":6,"reps":"30s on/30s off","rest":"—","muscleGroup":"Cardio","notes":"Sprint at 90% effort for 30 seconds, jog lightly for 30"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('f6', 'CrossFit Style Training', 'High-intensity functional fitness modeled on CrossFit methodology. WODs combining Olympic lifts, gymnastics, and metabolic conditioning.', 'fitness', 'HIIT', 'Advanced', 0, 5, 60, array['Barbell', 'Pull-Up Bar', 'Jump Rope', 'Kettlebell', 'Box', 'Rings']::text[], 'Fitness', true, '#FF5722', 'Scale weight and movements to your ability — a properly scaled WOD delivers the same stimulus as Rx. Ego-lifting leads to injury.', '[{"id":"f6e1","name":"Power Clean","sets":5,"reps":"3","rest":"2 min","muscleGroup":"Full Body / Power","weight":"65–75% 1RM"},{"id":"f6e2","name":"Muscle-Up (or Pull-Up)","sets":3,"reps":"5 (or 10)","rest":"90s","muscleGroup":"Back / Chest / Core"},{"id":"f6e3","name":"Box Jump","sets":4,"reps":"8","rest":"60s","muscleGroup":"Legs / Power"},{"id":"f6e4","name":"Kettlebell Swing","sets":4,"reps":"20","rest":"45s","muscleGroup":"Posterior Chain","weight":"35–53 lbs"},{"id":"f6e5","name":"Double-Under Jump Rope","sets":3,"reps":"50","rest":"60s","muscleGroup":"Cardio","notes":"Sub 100 single-unders if double-unders not yet mastered"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('f7', 'HIIT Shred Program', '8 weeks of science-backed high-intensity interval training. Short, brutal, effective — sessions under 35 minutes that torch fat long after you finish.', 'fitness', 'HIIT', 'Intermediate', 8, 4, 30, array['Mat', 'Dumbbells (optional)']::text[], 'Fitness', false, '#FF6B35', 'HIIT creates an "afterburn" that keeps metabolism elevated for 24 hours. Never train HIIT on consecutive days — recovery is when results happen.', '[{"id":"f7e1","name":"Sprint in Place","sets":1,"reps":"30s","rest":"10s","muscleGroup":"Cardio"},{"id":"f7e2","name":"Explosive Squat Jump","sets":1,"reps":"20s","rest":"10s","muscleGroup":"Legs / Power"},{"id":"f7e3","name":"Push-Up Burpee","sets":1,"reps":"30s","rest":"10s","muscleGroup":"Full Body"},{"id":"f7e4","name":"High Knees","sets":1,"reps":"30s","rest":"10s","muscleGroup":"Cardio / Core"},{"id":"f7e5","name":"Rest Complete","sets":1,"reps":"90s","rest":"—","muscleGroup":"—","notes":"Complete 6–8 full rounds of the circuit above"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('f8', 'Functional Fitness', 'Train movements, not muscles. 10 weeks of functional training that makes everyday life and sport easier — carry, push, pull, squat, hinge, rotate.', 'fitness', 'Functional Fitness', 'Intermediate', 10, 4, 45, array['Dumbbells', 'Kettlebell', 'Resistance Bands', 'TRX or Rings']::text[], 'Fitness', false, '#795548', 'Train barefoot or in minimal shoes when possible — it improves foot strength and proprioception, making every movement more stable.', '[{"id":"f8e1","name":"Turkish Get-Up","sets":3,"reps":"3 each side","rest":"90s","muscleGroup":"Full Body / Stability","weight":"15–35 lbs"},{"id":"f8e2","name":"KB Deadlift to High Pull","sets":4,"reps":"10","rest":"60s","muscleGroup":"Posterior Chain / Shoulders","weight":"35–53 lbs"},{"id":"f8e3","name":"TRX Row","sets":3,"reps":"12","rest":"60s","muscleGroup":"Back / Biceps / Core"},{"id":"f8e4","name":"Lateral Lunge to Balance","sets":3,"reps":"10 each","rest":"45s","muscleGroup":"Glutes / Adductors / Balance"},{"id":"f8e5","name":"Pallof Press","sets":3,"reps":"12 each","rest":"45s","muscleGroup":"Core / Anti-Rotation","notes":"Resist rotation throughout — key movement for injury-resistant core"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('s1', 'Beginner Weightlifting', 'An 8-week foundational program. Learn the big movements with perfect form and set personal records every single week.', 'strength', 'Beginner Weightlifting', 'Beginner', 8, 3, 60, array['Barbell', 'Dumbbells', 'Bench', 'Squat Rack']::text[], 'Strength', false, '#9C27B0', 'Never sacrifice form for weight. Start lighter than you think — adding 5 lbs per week is 260 lbs gained over a year.', '[{"id":"s1e1","name":"Barbell Squat","sets":3,"reps":"5","rest":"3 min","muscleGroup":"Legs / Core","weight":"Start 45–65 lbs","notes":"Focus on depth and knees tracking over toes"},{"id":"s1e2","name":"Barbell Bench Press","sets":3,"reps":"5","rest":"3 min","muscleGroup":"Chest / Triceps","weight":"Start 45–65 lbs"},{"id":"s1e3","name":"Barbell Deadlift","sets":1,"reps":"5","rest":"3 min","muscleGroup":"Full Posterior Chain","weight":"Start 65–95 lbs","notes":"1 work set per session — quality over quantity"},{"id":"s1e4","name":"Barbell Overhead Press","sets":3,"reps":"5","rest":"3 min","muscleGroup":"Shoulders / Triceps","weight":"Start 35–55 lbs"},{"id":"s1e5","name":"Barbell Row","sets":3,"reps":"5","rest":"3 min","muscleGroup":"Back / Biceps","weight":"Start 45–65 lbs"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Squat / Bench / Row","duration":60,"type":"strength"},{"day":"Tuesday","label":"Rest","duration":0,"type":"rest"},{"day":"Wednesday","label":"Squat / Press / Deadlift","duration":60,"type":"strength"},{"day":"Thursday","label":"Rest","duration":0,"type":"rest"},{"day":"Friday","label":"Squat / Bench / Row","duration":60,"type":"strength"},{"day":"Saturday","label":"Rest","duration":0,"type":"rest"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('s2', 'Powerlifting Peak Program', '16-week periodized powerlifting program. Maximize your squat, bench, and deadlift using block periodization and a structured peaking phase.', 'strength', 'Powerlifting', 'Advanced', 16, 4, 90, array['Barbell', 'Squat Rack', 'Bench', 'Belt', 'Knee Sleeves']::text[], 'Strength', true, '#795548', 'The peaking block (weeks 13–16) reduces volume and tapers to PR attempts. Feeling "less" in the final weeks means your CNS is peaking.', '[{"id":"s2e1","name":"Competition Squat","sets":4,"reps":"3","rest":"4 min","muscleGroup":"Legs / Core","weight":"80–92% 1RM"},{"id":"s2e2","name":"Competition Bench Press","sets":4,"reps":"3","rest":"4 min","muscleGroup":"Chest / Triceps","weight":"80–92% 1RM"},{"id":"s2e3","name":"Competition Deadlift","sets":4,"reps":"2","rest":"5 min","muscleGroup":"Full Posterior Chain","weight":"80–92% 1RM"},{"id":"s2e4","name":"Pause Squat","sets":3,"reps":"3","rest":"3 min","muscleGroup":"Quads / Core","weight":"70% 1RM","notes":"3-second pause — builds strength out of the hole"},{"id":"s2e5","name":"Close-Grip Bench Press","sets":3,"reps":"5","rest":"3 min","muscleGroup":"Triceps / Chest","weight":"65% 1RM"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('s3', 'Olympic Weightlifting', '12-week program developing the snatch and clean & jerk from fundamentals through full lifts. Explosive, technical, and deeply rewarding.', 'strength', 'Olympic Lifting', 'Advanced', 12, 4, 75, array['Barbell', 'Bumper Plates', 'Squat Rack', 'Lifting Shoes']::text[], 'Strength', true, '#D6A84B', 'Record every lift on video. More errors are caught on film than in the mirror. The overhead squat exposes every mobility limitation.', '[{"id":"s3e1","name":"Power Snatch","sets":5,"reps":"3","rest":"3 min","muscleGroup":"Full Body / Power","weight":"65–75% 1RM"},{"id":"s3e2","name":"Clean & Jerk","sets":5,"reps":"2+1","rest":"3 min","muscleGroup":"Full Body / Power","weight":"70–80% 1RM","notes":"2 cleans + 1 jerk"},{"id":"s3e3","name":"Front Squat","sets":4,"reps":"3","rest":"2 min","muscleGroup":"Quads / Core","weight":"80–85% 1RM"},{"id":"s3e4","name":"Snatch Deadlift","sets":4,"reps":"4","rest":"2 min","muscleGroup":"Posterior Chain","weight":"90–100% snatch max","notes":"Reinforces correct pull path"},{"id":"s3e5","name":"Overhead Squat","sets":3,"reps":"5","rest":"2 min","muscleGroup":"Stability / Full Body"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('s4', 'Strength & Conditioning', '12 weeks of concurrent training that builds muscle, maximal strength, and real conditioning — the best of both worlds.', 'strength', 'Strength & Conditioning', 'Intermediate', 12, 4, 60, array['Barbell', 'Dumbbells', 'Pull-Up Bar', 'Sled (optional)', 'Kettlebell']::text[], 'Strength', false, '#2F80FF', 'Do strength work before conditioning — fatigued muscles make for poor motor patterns on heavy lifts, which leads to injury.', '[{"id":"s4e1","name":"Barbell Squat","sets":4,"reps":"5","rest":"2 min","muscleGroup":"Legs / Core","weight":"75–80% 1RM"},{"id":"s4e2","name":"Push Press","sets":4,"reps":"5","rest":"2 min","muscleGroup":"Shoulders / Triceps / Legs","weight":"60–70% 1RM"},{"id":"s4e3","name":"Weighted Pull-Up","sets":3,"reps":"5","rest":"2 min","muscleGroup":"Back / Biceps"},{"id":"s4e4","name":"Sled Push","sets":4,"reps":"30m","rest":"90s","muscleGroup":"Full Body / Conditioning"},{"id":"s4e5","name":"Assault Bike Sprint","sets":5,"reps":"15s","rest":"45s","muscleGroup":"Cardio / Full Body","notes":"Max effort — brutal but effective"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Lower Strength + Sled","duration":65,"type":"strength"},{"day":"Tuesday","label":"Conditioning","duration":30,"type":"conditioning"},{"day":"Wednesday","label":"Upper Strength","duration":65,"type":"strength"},{"day":"Thursday","label":"Rest","duration":0,"type":"rest"},{"day":"Friday","label":"Full Body + Bike Intervals","duration":60,"type":"strength"},{"day":"Saturday","label":"Active Recovery","duration":30,"type":"recovery"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('r1', 'Couch to 5K', 'Transform from non-runner to confident 5K finisher in 8 weeks. Walk-run intervals that build your aerobic base without injury.', 'running', 'Beginner Running', 'Beginner', 8, 3, 30, array['Running Shoes']::text[], 'Running', false, '#35C98A', 'You should be able to hold a conversation while running — if you cannot, slow down. Building aerobic base takes months; there are no shortcuts.', '[{"id":"r1e1","name":"Warmup Walk","sets":1,"reps":"5 min","rest":"—","muscleGroup":"Full Body / Cardio"},{"id":"r1e2","name":"Run/Walk Intervals","sets":1,"reps":"20 min","rest":"—","muscleGroup":"Cardio","notes":"Week 1: 60s run / 90s walk × 8. Intervals lengthen each week"},{"id":"r1e3","name":"Cooldown Walk","sets":1,"reps":"5 min","rest":"—","muscleGroup":"Full Body / Cardio"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Run Session","duration":30,"type":"conditioning"},{"day":"Tuesday","label":"Rest","duration":0,"type":"rest"},{"day":"Wednesday","label":"Run Session","duration":30,"type":"conditioning"},{"day":"Thursday","label":"Rest","duration":0,"type":"rest"},{"day":"Friday","label":"Rest","duration":0,"type":"rest"},{"day":"Saturday","label":"Long Run","duration":35,"type":"conditioning"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('r2', '5K Race Ready', '8-week structured 5K plan. Easy runs, tempo efforts, and speed work that build your fitness to PR on race day.', 'running', '5K', 'Beginner', 8, 4, 30, array['Running Shoes', 'GPS Watch (optional)']::text[], 'Running', false, '#4CAF50', 'Run your easy days truly easy — most runners run easy days too hard, making hard days too slow. Trust the easy pace.', '[{"id":"r2e1","name":"Easy Run","sets":1,"reps":"20–30 min","rest":"—","muscleGroup":"Cardio","notes":"Conversational pace — full sentences throughout"},{"id":"r2e2","name":"Tempo Run","sets":1,"reps":"15–20 min","rest":"—","muscleGroup":"Cardio","notes":"Comfortably hard — short phrases only"},{"id":"r2e3","name":"400m Repeats","sets":4,"reps":"400m","rest":"90s","muscleGroup":"Cardio / Speed","distance":"400m","notes":"5K race pace effort each repeat"},{"id":"r2e4","name":"Long Run","sets":1,"reps":"35–45 min","rest":"—","muscleGroup":"Aerobic Endurance"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Easy Run","duration":25,"type":"conditioning"},{"day":"Tuesday","label":"Rest","duration":0,"type":"rest"},{"day":"Wednesday","label":"Tempo Run","duration":30,"type":"speed"},{"day":"Thursday","label":"400m Repeats","duration":35,"type":"speed"},{"day":"Friday","label":"Rest","duration":0,"type":"rest"},{"day":"Saturday","label":"Long Run","duration":45,"type":"conditioning"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('r3', '10K Training Plan', '10-week progression from 5K fitness to 10K race-readiness. Longer tempo work, progressive long runs, and race-specific intervals.', 'running', '10K', 'Intermediate', 10, 4, 40, array['Running Shoes', 'GPS Watch']::text[], 'Running', false, '#2F80FF', 'Pacing discipline separates finishers from runners who blow up. Practice goal pace on tempo days so it feels natural on race day.', '[{"id":"r3e1","name":"Easy Recovery Run","sets":1,"reps":"30 min","rest":"—","muscleGroup":"Cardio"},{"id":"r3e2","name":"10K Tempo Run","sets":1,"reps":"25–30 min","rest":"—","muscleGroup":"Cardio","notes":"Hold goal 10K race pace — the key workout of the week"},{"id":"r3e3","name":"1K Repeats","sets":5,"reps":"1 km","rest":"2 min","muscleGroup":"Cardio / Speed","distance":"1 km","notes":"Slightly faster than 10K goal pace each repeat"},{"id":"r3e4","name":"Long Run","sets":1,"reps":"60–75 min","rest":"—","muscleGroup":"Aerobic Endurance"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('r4', 'Half Marathon Program', '16-week half marathon plan. Progressive mileage, tune-up races, and a smart taper ensure you arrive at the start line ready to run your best.', 'running', 'Half Marathon', 'Intermediate', 16, 4, 60, array['Running Shoes', 'GPS Watch', 'Energy Gels']::text[], 'Running', true, '#D6A84B', 'The long run is the cornerstone of half marathon training. Do it 60–90 seconds per mile slower than race pace — your race-day legs will thank you.', '[{"id":"r4e1","name":"Easy Base Run","sets":1,"reps":"40 min","rest":"—","muscleGroup":"Cardio"},{"id":"r4e2","name":"Half Marathon Tempo","sets":1,"reps":"30–40 min","rest":"—","muscleGroup":"Cardio","notes":"Race goal pace — builds confidence and fitness together"},{"id":"r4e3","name":"Long Run (Negative Split)","sets":1,"reps":"90–120 min","rest":"—","muscleGroup":"Aerobic Endurance","notes":"Run second half slightly faster than first"},{"id":"r4e4","name":"Strides","sets":6,"reps":"20s","rest":"1 min","muscleGroup":"Speed / Neuromuscular","notes":"Relaxed accelerations to 95% — improves running economy"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('r5', 'Marathon Training Plan', '20-week marathon plan: progressive long runs, back-to-back weekend sessions, and a structured 3-week taper.', 'running', 'Marathon', 'Advanced', 20, 5, 90, array['Running Shoes', 'GPS Watch', 'Energy Gels', 'Hydration Vest']::text[], 'Running', true, '#FF6B35', 'Practice your race-day nutrition on every long run above 16 miles. Gut issues are almost always preventable with proper rehearsal.', '[{"id":"r5e1","name":"Easy Recovery Run","sets":1,"reps":"45–60 min","rest":"—","muscleGroup":"Cardio"},{"id":"r5e2","name":"Marathon Pace Run","sets":1,"reps":"10–14 miles","rest":"—","muscleGroup":"Cardio","distance":"10–14 miles","notes":"Goal marathon pace — most important run of the week"},{"id":"r5e3","name":"Progression Long Run","sets":1,"reps":"18–22 miles","rest":"—","muscleGroup":"Aerobic Endurance","distance":"18–22 miles"},{"id":"r5e4","name":"Midweek Medium-Long Run","sets":1,"reps":"12–15 miles","rest":"—","muscleGroup":"Aerobic Base","distance":"12–15 miles"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Rest","duration":0,"type":"rest"},{"day":"Tuesday","label":"Easy Run","duration":50,"type":"conditioning"},{"day":"Wednesday","label":"Marathon Pace","duration":90,"type":"speed"},{"day":"Thursday","label":"Easy Run","duration":45,"type":"conditioning"},{"day":"Friday","label":"Rest","duration":0,"type":"rest"},{"day":"Saturday","label":"Medium-Long Run","duration":80,"type":"conditioning"},{"day":"Sunday","label":"Long Run","duration":150,"type":"conditioning"}]'::jsonb, 'published'),
  ('r6', 'Sprint Speed Development', '8-week sprint program focused on acceleration, max velocity mechanics, and speed endurance. Get measurably faster.', 'running', 'Sprint Training', 'Intermediate', 8, 4, 45, array['Track or Turf Field', 'Resistance Bands']::text[], 'Running', false, '#D6A84B', 'Sprint work requires full recovery between reps. If your times are slowing down significantly, stop — you are training fatigue, not speed.', '[{"id":"r6e1","name":"10m Acceleration Sprint","sets":6,"reps":"10m","rest":"2 min","muscleGroup":"Full Body / Power","distance":"10m","notes":"Forward lean and powerful first 3 steps"},{"id":"r6e2","name":"40m Flying Sprint","sets":5,"reps":"40m","rest":"3 min","muscleGroup":"Speed / Power","distance":"40m","notes":"Start jogging, hit max velocity at 20m mark"},{"id":"r6e3","name":"Resisted Sprint (Band)","sets":4,"reps":"20m","rest":"3 min","muscleGroup":"Acceleration","distance":"20m","notes":"Partner resistance drives acceleration overload"},{"id":"r6e4","name":"150m Speed Endurance","sets":4,"reps":"150m","rest":"4 min","muscleGroup":"Speed Endurance","distance":"150m","notes":"90% effort — builds speed endurance"}]'::jsonb, '[]'::jsonb, '[{"day":"Monday","label":"Acceleration Work","duration":45,"type":"speed"},{"day":"Tuesday","label":"Lower Body Strength","duration":50,"type":"strength"},{"day":"Wednesday","label":"Rest","duration":0,"type":"rest"},{"day":"Thursday","label":"Max Velocity","duration":45,"type":"speed"},{"day":"Friday","label":"Speed Endurance","duration":50,"type":"conditioning"},{"day":"Saturday","label":"Rest","duration":0,"type":"rest"},{"day":"Sunday","label":"Rest","duration":0,"type":"rest"}]'::jsonb, 'published'),
  ('rc1', 'Daily Mobility Flow', '6-week mobility program that systematically opens every major joint. 30-minute daily flows that reduce pain, improve posture, and enhance performance.', 'recovery', 'Mobility', 'Beginner', 6, 5, 30, array['Mat', 'Foam Roller', 'Resistance Band']::text[], 'Recovery', false, '#00BCD4', 'Breathe into each stretch — exhale and sink deeper into end range. Tension is your nervous system protecting you; teach it the new range is safe.', '[{"id":"rc1e1","name":"90/90 Hip Stretch","sets":1,"reps":"2 min each side","rest":"—","muscleGroup":"Hip Rotators"},{"id":"rc1e2","name":"Thoracic Spine Rotation","sets":1,"reps":"10 each side","rest":"—","muscleGroup":"Thoracic / Upper Back"},{"id":"rc1e3","name":"World''s Greatest Stretch","sets":1,"reps":"5 each side","rest":"—","muscleGroup":"Hips / Thoracic / Shoulders","notes":"Best single movement for total body mobility"},{"id":"rc1e4","name":"Ankle CARs","sets":1,"reps":"10 each direction per foot","rest":"—","muscleGroup":"Ankle / Lower Leg"},{"id":"rc1e5","name":"Cat-Cow Breath Flow","sets":1,"reps":"10 full breaths","rest":"—","muscleGroup":"Lumbar / Thoracic Spine"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('rc2', 'Flexibility & Stretching', '6-week daily stretching program targeting chronically tight muscles — hips, hamstrings, thoracic spine, and shoulders.', 'recovery', 'Stretching', 'Beginner', 6, 6, 20, array['Mat', 'Yoga Blocks (optional)', 'Strap or Towel']::text[], 'Recovery', false, '#4CAF50', 'Hold stretches for at least 60 seconds — research shows 30 seconds is not enough to create lasting flexibility change.', '[{"id":"rc2e1","name":"Supine Hamstring Stretch","sets":1,"reps":"90s each leg","rest":"—","muscleGroup":"Hamstrings","notes":"Use a strap to keep leg straight"},{"id":"rc2e2","name":"Pigeon Pose","sets":1,"reps":"90s each side","rest":"—","muscleGroup":"Glutes / Hip External Rotators"},{"id":"rc2e3","name":"Doorway Pec Stretch","sets":1,"reps":"60s each side","rest":"—","muscleGroup":"Chest / Anterior Shoulder"},{"id":"rc2e4","name":"Standing Quad Stretch","sets":1,"reps":"60s each leg","rest":"—","muscleGroup":"Quads / Hip Flexor"},{"id":"rc2e5","name":"Seated Spinal Twist","sets":1,"reps":"90s each side","rest":"—","muscleGroup":"Lumbar Spine / Obliques"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('rc3', 'Foam Rolling & Myofascial Release', 'Targeted foam rolling protocol for pre- and post-workout recovery. Releases tight fascia, reduces DOMS, and primes the nervous system.', 'recovery', 'Foam Rolling', 'Beginner', 0, 5, 20, array['Foam Roller', 'Lacrosse Ball']::text[], 'Recovery', false, '#607D8B', 'When you find a tender spot, pause on it 30–60 seconds rather than rolling back and forth. You want the tissue to release, not just the surface massaged.', '[{"id":"rc3e1","name":"IT Band Roll","sets":1,"reps":"60s each side","rest":"—","muscleGroup":"IT Band / Lateral Leg","notes":"Hip to knee slowly — pause on tender spots"},{"id":"rc3e2","name":"Thoracic Spine Roll","sets":1,"reps":"90s","rest":"—","muscleGroup":"Upper Back / T-Spine","notes":"Deep breath at each segment to open the spine"},{"id":"rc3e3","name":"Glute / Piriformis (Lacrosse Ball)","sets":1,"reps":"60s each side","rest":"—","muscleGroup":"Glutes / Hip Rotators"},{"id":"rc3e4","name":"Calf & Achilles Roll","sets":1,"reps":"60s each leg","rest":"—","muscleGroup":"Calf / Achilles"},{"id":"rc3e5","name":"Lat Roll","sets":1,"reps":"60s each side","rest":"—","muscleGroup":"Lats / Teres Major"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('rc4', 'Injury Prevention Protocol', '8-week proactive injury prevention program targeting the most commonly injured areas — ACL, rotator cuff, hamstrings, and lower back.', 'recovery', 'Injury Prevention', 'Intermediate', 8, 4, 35, array['Resistance Bands', 'Mat', 'Balance Board (optional)']::text[], 'Recovery', true, '#FF6B35', 'Injury prevention is not exciting — it is done before you need it. Athletes who never miss time did the boring prehab work consistently.', '[{"id":"rc4e1","name":"Nordic Hamstring Curl","sets":3,"reps":"5","rest":"2 min","muscleGroup":"Hamstrings","notes":"Most evidence-based ACL & hamstring injury prevention exercise"},{"id":"rc4e2","name":"Band Clamshell","sets":3,"reps":"20 each","rest":"45s","muscleGroup":"Glute Med / Hip Stabilizers","notes":"Weak glute med is the root cause of most knee alignment issues"},{"id":"rc4e3","name":"Rotator Cuff External Rotation","sets":3,"reps":"15 each","rest":"45s","muscleGroup":"Rotator Cuff"},{"id":"rc4e4","name":"Single-Leg RDL","sets":3,"reps":"10 each","rest":"60s","muscleGroup":"Hamstrings / Glutes / Balance"},{"id":"rc4e5","name":"Dead Bug","sets":3,"reps":"10 each","rest":"45s","muscleGroup":"Core / Lower Back","notes":"Press lower back into floor throughout — slow and controlled"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('rc5', 'Active Recovery Program', '6-week program for the days between hard training sessions. Light movement, breath work, and tissue work that accelerates recovery.', 'recovery', 'Recovery Sessions', 'Intermediate', 6, 5, 30, array['Mat', 'Foam Roller', 'Resistance Bands']::text[], 'Recovery', false, '#35C98A', 'Active recovery is not a day off — it is targeted low-intensity movement that flushes metabolic waste. It should feel restorative, not challenging.', '[{"id":"rc5e1","name":"Easy Walk or Light Jog","sets":1,"reps":"10 min","rest":"—","muscleGroup":"Full Body / Cardio","notes":"Zone 1 heart rate only — just enough to get blood moving"},{"id":"rc5e2","name":"Full Body Foam Roll","sets":1,"reps":"10 min","rest":"—","muscleGroup":"Connective Tissue"},{"id":"rc5e3","name":"Diaphragmatic Breathing","sets":1,"reps":"5 min","rest":"—","muscleGroup":"Nervous System","notes":"4 counts in, 6 counts out — activates rest-and-digest"},{"id":"rc5e4","name":"Yoga Flow (Sun Salutation)","sets":3,"reps":"1 full flow","rest":"30s","muscleGroup":"Full Body / Mobility"},{"id":"rc5e5","name":"Contrast Shower","sets":1,"reps":"3 min (30s cold/30s hot)","rest":"—","muscleGroup":"Recovery / Circulation","notes":"Reduces inflammation and speeds muscular recovery"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('w1', 'Power Walking for Fitness', '8-week progressive walking program that builds cardiovascular fitness, burns calories, and improves overall health without joint stress.', 'walking', 'Walking', 'Beginner', 8, 5, 40, array['Comfortable shoes', 'Water bottle']::text[], 'Cardio', false, '#8BC34A', 'Walk with intention — keep your core lightly engaged, shoulders relaxed, and eyes forward. A 20-minute brisk walk burns as many calories as a 15-minute jog for most people.', '[{"id":"w1e1","name":"Warm-Up Walk","sets":1,"reps":"5 min easy pace","rest":"—","muscleGroup":"Full Body / Cardio"},{"id":"w1e2","name":"Brisk Walk","sets":1,"reps":"25–35 min moderate pace","rest":"—","muscleGroup":"Legs / Cardio","notes":"Target 3.5–4 mph — you should be able to talk but feel slightly breathless"},{"id":"w1e3","name":"Incline Walk","sets":3,"reps":"3 min uphill","rest":"2 min flat","muscleGroup":"Glutes / Calves / Cardio"},{"id":"w1e4","name":"Cool-Down Walk","sets":1,"reps":"5 min slow pace","rest":"—","muscleGroup":"Full Body"},{"id":"w1e5","name":"Standing Calf Stretch","sets":2,"reps":"45s each leg","rest":"—","muscleGroup":"Calves"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published'),
  ('ct1', 'Cross-Training Challenge', '8-week mixed-modality program combining strength, cardio, and functional movements for total-body fitness and athletic endurance.', 'crosstraining', 'Cross-Training', 'Intermediate', 8, 4, 50, array['Dumbbells', 'Jump Rope', 'Rowing Machine (optional)', 'Mat']::text[], 'Cardio', false, '#FF5722', 'Cross-training is about variety — the combination of modalities challenges your body in new ways every session. Embrace the variety and trust the process.', '[{"id":"ct1e1","name":"Jump Rope Intervals","sets":5,"reps":"1 min on / 30s off","rest":"30s","muscleGroup":"Cardio / Calves / Coordination"},{"id":"ct1e2","name":"Dumbbell Thrusters","sets":4,"reps":"12","rest":"60s","muscleGroup":"Full Body / Shoulders / Legs"},{"id":"ct1e3","name":"Rowing Machine (or Row Subs)","sets":3,"reps":"500m","rest":"90s","muscleGroup":"Back / Arms / Cardio"},{"id":"ct1e4","name":"Box Jumps or Step-Ups","sets":4,"reps":"10","rest":"60s","muscleGroup":"Legs / Power / Cardio"},{"id":"ct1e5","name":"Turkish Get-Up","sets":3,"reps":"3 each side","rest":"90s","muscleGroup":"Full Body / Core / Stability"}]'::jsonb, '[]'::jsonb, '[]'::jsonb, 'published')
