-- 4 nutrition plans
insert into public.nutrition_plans (id, title, description, goal, daily_calories, protein, carbs, fat, is_premium, meals, status) values
  ('np1', 'Endurance Performance Plan', 'High-carb endurance nutrition plan — peak glycogen loading, optimal hydration, and performance-timed fuel.', 'Improve Endurance', 3400, 210, 420, 75, false, '[{"id":"m1","name":"Morning Activation","time":"7:00 AM","calories":700,"protein":45,"carbs":90,"fat":18,"foods":["Oatmeal with honey","Eggs (3)","Banana","Orange juice"]},{"id":"m2","name":"Pre-Workout Fuel","time":"11:00 AM","calories":800,"protein":55,"carbs":110,"fat":15,"foods":["Grilled chicken","White rice","Steamed vegetables","Gatorade"]},{"id":"m3","name":"Pre-Workout Snack","time":"1:00 PM","calories":350,"protein":25,"carbs":55,"fat":5,"foods":["Rice cakes","Peanut butter","Banana"]},{"id":"m4","name":"Mid-Session Refuel","time":"Half","calories":300,"protein":15,"carbs":55,"fat":5,"foods":["Sports drink","Orange slices","Energy chew"]},{"id":"m5","name":"Post-Workout Recovery","time":"6:00 PM","calories":900,"protein":65,"carbs":105,"fat":22,"foods":["Salmon","Sweet potato","Broccoli","Protein shake"]},{"id":"m6","name":"Night Recovery","time":"9:30 PM","calories":350,"protein":35,"carbs":30,"fat":10,"foods":["Cottage cheese","Cherries","Casein shake"]}]'::jsonb, 'published'),
  ('np2', 'Muscle Building Plan', 'High-calorie, protein-rich plan for building muscle — add functional size and strength while minimizing fat gain.', 'Build Muscle', 3800, 250, 440, 95, false, '[{"id":"m7","name":"Power Breakfast","time":"7:00 AM","calories":850,"protein":55,"carbs":100,"fat":25,"foods":["6 eggs","Oatmeal","Whole milk","Banana","Almond butter"]},{"id":"m8","name":"Mid-Morning","time":"10:00 AM","calories":550,"protein":45,"carbs":65,"fat":14,"foods":["Greek yogurt","Protein bar","Trail mix"]},{"id":"m9","name":"Pre-Training","time":"12:30 PM","calories":750,"protein":55,"carbs":95,"fat":18,"foods":["Ground beef","Brown rice","Avocado"]},{"id":"m10","name":"Post-Training","time":"3:30 PM","calories":700,"protein":65,"carbs":85,"fat":12,"foods":["Whey shake","White rice","Banana","Chocolate milk"]},{"id":"m11","name":"Dinner","time":"7:00 PM","calories":950,"protein":75,"carbs":95,"fat":26,"foods":["Steak (8oz)","Pasta","Broccoli","Olive oil"]}]'::jsonb, 'published'),
  ('np3', 'Active Training Fuel', 'Periodized nutrition built around your training schedule — fuel up on heavy days, recover smart on light days.', 'Improve Endurance', 3000, 210, 340, 78, true, '[{"id":"m12","name":"Early Morning","time":"6:00 AM","calories":550,"protein":38,"carbs":65,"fat":16,"foods":["Overnight oats","Whey protein","Blueberries"]},{"id":"m13","name":"Pre-Training Fuel","time":"10:30 AM","calories":700,"protein":50,"carbs":85,"fat":15,"foods":["Turkey wrap","Rice cakes","Apple"]},{"id":"m14","name":"Post-Training Recovery","time":"2:00 PM","calories":750,"protein":60,"carbs":90,"fat":17,"foods":["Chocolate milk","Sweet potato","Chicken breast"]},{"id":"m15","name":"Dinner","time":"7:00 PM","calories":700,"protein":52,"carbs":75,"fat":20,"foods":["Salmon","Quinoa","Mixed greens","Olive oil"]},{"id":"m16","name":"Night Recovery","time":"10:00 PM","calories":300,"protein":30,"carbs":25,"fat":10,"foods":["Casein shake","Walnuts","Tart cherry juice"]}]'::jsonb, 'published'),
  ('np4', 'Weight Loss Protocol', 'Structured plan for managing body composition — maintain performance while hitting your target weight.', 'Lose Weight', 2400, 215, 220, 65, true, '[{"id":"m17","name":"Morning","time":"7:00 AM","calories":500,"protein":45,"carbs":45,"fat":14,"foods":["Egg whites (6)","Spinach","Whole grain toast","Black coffee"]},{"id":"m18","name":"Midday Fuel","time":"12:00 PM","calories":650,"protein":60,"carbs":65,"fat":16,"foods":["Grilled chicken","Brown rice","Cucumber salad"]},{"id":"m19","name":"Pre-Train","time":"3:00 PM","calories":400,"protein":35,"carbs":50,"fat":8,"foods":["Protein shake","Rice cakes","Banana"]},{"id":"m20","name":"Dinner","time":"7:00 PM","calories":650,"protein":65,"carbs":55,"fat":20,"foods":["Tilapia","Cauliflower rice","Asparagus","Lemon"]},{"id":"m21","name":"Night Snack","time":"9:30 PM","calories":200,"protein":25,"carbs":10,"fat":7,"foods":["Cottage cheese","Cucumber"]}]'::jsonb, 'published')
