insert into public.rehab_programs (id, title, description, body_part, duration, phases, exercises, status) values
  ('rp1', 'Lower Back Recovery', 'Evidence-based protocol to heal lower back pain — one of the most common training injuries.', 'Lower Back', '6-8 weeks', 3, '[{"id":"re1","name":"Cat-Cow Stretch","sets":2,"reps":"10","rest":"30 sec","muscleGroup":"Spine"},{"id":"re2","name":"Bird Dog","sets":3,"reps":"10 each","rest":"45 sec","muscleGroup":"Core"},{"id":"re3","name":"Dead Bug","sets":3,"reps":"8 each","rest":"45 sec","muscleGroup":"Core"},{"id":"re4","name":"Glute Bridge","sets":3,"reps":"15","rest":"60 sec","muscleGroup":"Glutes"},{"id":"re5","name":"Child''s Pose","sets":3,"reps":"60 sec","rest":"30 sec","muscleGroup":"Back"}]'::jsonb, 'published'),
  ('rp2', 'Shoulder Rehabilitation', 'Restore shoulder mobility and strength after impact, throwing overuse, or blocking stress.', 'Shoulder', '8-10 weeks', 4, '[{"id":"re6","name":"Pendulum Swings","sets":3,"reps":"30 sec","rest":"30 sec","muscleGroup":"Shoulder"},{"id":"re7","name":"Band External Rotation","sets":3,"reps":"15","rest":"45 sec","muscleGroup":"Rotator Cuff"},{"id":"re8","name":"Scapular Wall Slides","sets":3,"reps":"12","rest":"45 sec","muscleGroup":"Upper Back"},{"id":"re9","name":"Prone Y-T-W","sets":3,"reps":"10","rest":"60 sec","muscleGroup":"Shoulder"}]'::jsonb, 'published'),
  ('rp3', 'Knee & ACL Recovery', 'Step-by-step protocol for ACL, meniscus, or general knee recovery.', 'Knee', '10-16 weeks', 5, '[{"id":"re10","name":"Quad Sets","sets":3,"reps":"15","rest":"30 sec","muscleGroup":"Quads"},{"id":"re11","name":"Straight Leg Raise","sets":3,"reps":"15","rest":"45 sec","muscleGroup":"Quads"},{"id":"re12","name":"Single-Leg Balance Progression","sets":3,"reps":"30 sec each","rest":"45 sec","muscleGroup":"Stability"},{"id":"re13","name":"Terminal Knee Extension","sets":3,"reps":"15","rest":"45 sec","muscleGroup":"Quads"},{"id":"re14","name":"Hip Abduction Series","sets":3,"reps":"15","rest":"45 sec","muscleGroup":"Hips"}]'::jsonb, 'published'),
  ('rp4', 'Hamstring & Hip Recovery', 'Targeted recovery for hamstring strains and hip flexor injuries.', 'Hamstring / Hip', '4-8 weeks', 3, '[{"id":"re15","name":"90/90 Hip Stretch","sets":3,"reps":"60 sec","rest":"30 sec","muscleGroup":"Hip Flexor"},{"id":"re16","name":"Nordic Hamstring Curl","sets":3,"reps":"6-8","rest":"90 sec","muscleGroup":"Hamstrings"},{"id":"re17","name":"Prone Hip Extension","sets":3,"reps":"12 each","rest":"45 sec","muscleGroup":"Glutes"},{"id":"re18","name":"Eccentric Hamstring Slide","sets":3,"reps":"8 each","rest":"60 sec","muscleGroup":"Hamstrings"}]'::jsonb, 'published')
